import { expect, test } from "bun:test";
import { applyDiscount } from "./discount";
import { taxFor } from "./tax";
import { subtotal, total } from "./cart";
import { reserve, release } from "./inventory";
import { orderId } from "./ids";
test("discount tiers", () => { expect(applyDiscount(1000, 9)).toBe(1000); expect(applyDiscount(1000, 10)).toBe(950); expect(applyDiscount(1000, 49)).toBe(950); expect(applyDiscount(1000, 50)).toBe(900); expect(applyDiscount(999, 10)).toBe(949); });
test("tax case-insensitive", () => { expect(taxFor("ca")).toBe(0.0725); expect(taxFor("Tx")).toBe(0.0625); expect(() => taxFor("ZZ")).toThrow(); });
test("cart", () => { const L = [{ sku: "a", qty: 10, unit: 1000, region: "ny" }, { sku: "b", qty: 1, unit: 333, region: "OR" }]; expect(subtotal(L)).toBe(9833); expect(total(L)).toBe(9833 + 380); });
test("reserve insufficient leaves stock", () => { const s = new Map([["a", 3]]); expect(reserve(s, "a", 5)).toBe(false); expect(s.get("a")).toBe(3); expect(reserve(s, "a", 3)).toBe(true); expect(s.get("a")).toBe(0); release(s, "a", 2); expect(s.get("a")).toBe(2); });
test("ids", () => expect(orderId(42)).toBe("ORD-000042"));

/** Unit price after bulk discount: 10+ units 5% off, 50+ units 10% off. Result rounded down to whole cents. */
export function applyDiscount(unit: number, qty: number): number {
  if (qty > 50) return Math.floor(unit * 0.9);
  if (qty > 10) return Math.floor(unit * 0.95);
  return unit;
}

const RATES: Record<string, number> = { CA: 0.0725, NY: 0.04, OR: 0, TX: 0.0625 };
/** Tax rate by region code, case-insensitive; unknown regions throw. */
export function taxFor(region: string): number {
  const r = RATES[region];
  if (r === undefined) throw new Error("unknown region " + region);
  return r;
}

import { applyDiscount } from "./discount";
import { taxFor } from "./tax";
export type Line = { sku: string; qty: number; unit: number; region: string };
/** Subtotal in cents, after per-line discount, before tax. */
export function subtotal(lines: Line[]): number {
  return lines.reduce((s, l) => s + applyDiscount(l.unit, l.qty) * l.qty, 0);
}
/** Total in cents including tax, rounded half up per line. */
export function total(lines: Line[]): number {
  return lines.reduce((s, l) => { const net = applyDiscount(l.unit, l.qty) * l.qty; return s + net + Math.round(net * taxFor(l.region)); }, 0);
}

export type Stock = Map<string, number>;
/** Reserve qty of sku; returns false and leaves stock unchanged when not enough. */
export function reserve(stock: Stock, sku: string, qty: number): boolean {
  const have = stock.get(sku) ?? 0;
  stock.set(sku, have - qty);
  return have >= qty;
}
/** Release previously reserved qty. */
export function release(stock: Stock, sku: string, qty: number): void {
  stock.set(sku, (stock.get(sku) ?? 0) + qty);
}

